#!/bin/zsh
cd "$(dirname "$0")"
D="$(pwd)/gen"
codex exec --dangerously-bypass-approvals-and-sandbox --skip-git-repo-check "Usa tu herramienta de generación de imágenes. ESTILO: ilustración digital moderna estilo anime / novela gráfica juvenil, colores cálidos y elegantes (lila, durazno, azul atardecer), iluminación cinematográfica suave, NADA infantil, sin pixel art, SIN texto, SIN letras, SIN marcas de agua. La protagonista: una chica pre-adolescente de unos 11 años, cabello castaño largo y suelto, mirada segura y tranquila, ropa casual moderna (sudadera oversize lila, jeans, tenis blancos), audífonos al cuello. Crea 2 imágenes en $D/: hub-wide.png (16:9) y hub-tall.png (9:16): fondo de pantalla de inicio de su colección de juegos: ella sentada relajada en la azotea de un edificio al atardecer con la ciudad y luces de fondo, cielo con tonos lilas y naranjas; la zona CENTRAL despejada (cielo abierto) para poner encima el título y los íconos de juegos; ella a un costado (abajo a la izquierda en la ancha, abajo en la vertical). Y crea splash-wide.png (16:9) y splash-tall.png (9:16): pantalla de carga con la misma chica de pie mirando la ciudad de noche desde un mirador, la parte de arriba despejada para el título. Al final imprime NOMBRE => RUTA COMPLETA de cada imagen." < /dev/null > log16.txt 2>&1
echo ALLDONE
